solution.referenceCode:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>

#define N 4

int main(void) {
    for (int i = 0; i < N; i++) {
        pid_t pid = fork();
        if (pid < 0) { perror("fork"); exit(EXIT_FAILURE); }
        if (pid == 0) {
            exit(EXIT_SUCCESS);
        }
    }
    int recuperes = 0;
    while (wait(NULL) > 0) {
        recuperes++;
    }
    printf("fils recuperes = %d\n", recuperes);
    return 0;
}

